// Follow-up de orcamentos: 10h locais do dono, 3+ dias sem resposta.
// Webhook manual aceita {force: '<numero>'} pra teste (ignora hora e NAO marca).
let force = '';
try { const b = items[0].json.body || items[0].json; force = String(b.force || '').replace(/[^0-9]/g, ''); } catch (e) {}
const cols = `o.id, o.dono_numero, o.numero, o.cliente_final, o.valor, o.moeda, o.status, o.validade_dias`;
const extras = `d.nome AS dono_nome, d.idioma,
       EXTRACT(DAY FROM NOW() - o.criado_em)::int AS dias,
       (NOW() > o.criado_em + make_interval(days => COALESCE(o.validade_dias, 15))) AS vencido`;
let sql;
if (force) {
  sql = `SELECT ${cols}, ${extras}
FROM giulia_orcamentos o JOIN giulia_donos d ON d.numero = o.dono_numero
WHERE o.dono_numero = '${force}' AND o.status IN ('gerado','enviado')
ORDER BY o.criado_em DESC LIMIT 5;`;
} else {
  sql = `WITH alvo AS (
  SELECT o.id FROM giulia_orcamentos o
  JOIN giulia_donos d ON d.numero = o.dono_numero
  WHERE o.status IN ('gerado','enviado')
    AND COALESCE(d.status, 'ativo') = 'ativo'
    AND to_char(NOW() AT TIME ZONE d.timezone, 'HH24')::int = 10
    AND COALESCE(o.ultimo_followup, o.criado_em) < NOW() - INTERVAL '3 days'
  FOR UPDATE OF o SKIP LOCKED
  LIMIT 20
), upd AS (
  UPDATE giulia_orcamentos o2 SET ultimo_followup = NOW(), atualizado_em = NOW()
  FROM alvo WHERE o2.id = alvo.id
  RETURNING o2.id, o2.dono_numero, o2.numero, o2.cliente_final, o2.valor, o2.moeda, o2.status, o2.validade_dias, o2.criado_em
)
SELECT u.id, u.dono_numero, u.numero, u.cliente_final, u.valor, u.moeda, u.status, u.validade_dias,
       d.nome AS dono_nome, d.idioma,
       EXTRACT(DAY FROM NOW() - u.criado_em)::int AS dias,
       (NOW() > u.criado_em + make_interval(days => COALESCE(u.validade_dias, 15))) AS vencido
FROM upd u JOIN giulia_donos d ON d.numero = u.dono_numero;`;
}
return [{ json: { sql, force: force || null } }];

// Uma mensagem de follow-up POR DONO (consolida todos os orcamentos do dia)
const porDono = {};
for (const it of items) {
  const o = it.json;
  if (!o || !o.id) continue;
  (porDono[o.dono_numero] = porDono[o.dono_numero] || []).push(o);
}
const out = [];
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
for (const dono of Object.keys(porDono)) {
  const orcs = porDono[dono];
  const en = String(orcs[0].idioma || 'pt').toLowerCase() === 'en';
  const linha = o => {
    const mSym = o.moeda === 'USD' ? '$' : 'R$';
    const val = (o.valor != null && o.valor !== '')
      ? mSym + ' ' + String(Math.round(Number(o.valor))).replace(/\B(?=(\d{3})+(?!\d))/g, '.')
      : '';
    return `• ${o.numero} — ${o.cliente_final}${val ? ' (' + val + ')' : ''}, ${o.dias}d sem resposta${o.vencido ? (en ? ' [expired]' : ' [validade vencida]') : ''}`;
  };
  let texto;
  if (orcs.length === 1) {
    const o = orcs[0];
    const mSym = o.moeda === 'USD' ? '$' : 'R$';
    const val = (o.valor != null && o.valor !== '')
      ? mSym + ' ' + String(Math.round(Number(o.valor))).replace(/\B(?=(\d{3})+(?!\d))/g, '.')
      : '';
    if (en) {
      texto = `Quote ${o.numero} (${o.cliente_final}${val ? ', ' + val : ''}) has been out ${o.dias} days with no update. Any news? Tell me 'approved' or 'declined' and I log it.`;
      if (o.vencido) texto += ` Heads up: it is past its validity - want me to generate a fresh one?`;
    } else {
      texto = `O orcamento ${o.numero} (${o.cliente_final}${val ? ', ' + val : ''}) ta ha ${o.dias} dias sem resposta. Teve retorno? Me fala 'aprovou' ou 'recusou' que eu atualizo aqui.`;
      if (o.vencido) texto += ` Detalhe: a validade ja venceu - se quiser eu gero um novo.`;
    }
  } else {
    texto = en
      ? `Quick follow-up on your open quotes:\n` + orcs.map(linha).join('\n') + `\nAny updates? Tell me per client, e.g. '${orcs[0].cliente_final} approved'.`
      : `Follow-up dos teus orcamentos em aberto:\n` + orcs.map(linha).join('\n') + `\nTeve retorno de algum? Me fala por cliente, tipo '${orcs[0].cliente_final} aprovou' ou 'recusou'.`;
  }
  out.push({ json: {
    number: dono,
    texto,
    memoria_sql: "INSERT INTO giulia_memoria (role, content, from_numero) VALUES ('assistant', '" + esc(texto) + "', '" + esc(dono) + "');"
  } });
}
return out;
